<script setup lang="ts">
import {computed} from 'vue';
const props=defineProps<{phase:string;title?:string;error?:string;ready?:boolean}>();
const stages=[{id:'PREPARING_RESOURCES',label:'整理课程材料',description:'正在为首段讲解准备已授权的课程资料。'},{id:'GENERATING_CONTENT',label:'编写课堂讲解',description:'正在根据确认的大纲组织讲解与学习内容。'},{id:'PUBLISHING',label:'校验并发布',description:'首段内容正在通过检查，通过后即可进入课堂。'}];
const active=computed(()=>Math.max(0,stages.findIndex(stage=>stage.id===props.phase)));
const label=computed(()=>props.error?'课堂准备遇到问题':props.ready?'课堂已准备好':stages[active.value]!.label);
const description=computed(()=>props.error|| (props.ready?'首段讲解已就绪，可以开始学习。':stages[active.value]!.description));
const visual=computed(()=>props.error?'error':props.ready?'ready':props.phase==='PUBLISHING'?'publishing':props.phase==='GENERATING_CONTENT'?'content':'resources');
</script>
<template>
 <section class="preparation-card" aria-label="课堂准备进度" :aria-busy="!ready&&!error" :class="{'has-error':!!error}">
  <ol class="preparation-dots" aria-label="课堂准备阶段"><li v-for="(stage,index) in stages" :key="stage.id" :class="{current:index===active,done:ready||index<active}" :aria-current="!ready&&index===active?'step':undefined"><span class="sr-only">{{stage.label}}</span></li></ol>
  <div class="preparation-body">
   <div class="preparation-visual" aria-hidden="true">
    <Transition name="content-stage" mode="out-in">
     <div v-if="visual==='error'||visual==='ready'" :key="visual" class="result-circle"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="3"><template v-if="visual==='ready'"><path d="m17 33 10 10 21-23"/></template><template v-else><path d="M32 16v22m0 7v3"/></template></svg></div>
     <div v-else-if="visual==='publishing'" key="publishing" class="publication-timeline"><div class="mini-toolbar"><span>✓</span><i/></div><div class="timeline-rows"><div v-for="(stage,index) in stages" :key="stage.id" :class="{active:index===active}"><span>{{index<active?'✓':'○'}}</span><strong>{{stage.label}}</strong><i/></div></div></div>
     <div v-else :key="visual" class="content-orbit"><span class="orbit orbit-one"/><span class="orbit orbit-two"/><div class="mini-content"><span class="content-badge">{{visual==='content'?'讲解':'资料'}}</span><i class="mini-title"/><div class="mini-columns"><div><i v-for="(width,index) in [80,90,60,70]" :key="index" :style="{width:width+'%','--delay':index*.1+'s'}"/></div><div class="mini-chart"><span/><span/><span/></div></div></div></div>
    </Transition>
   </div>
   <div class="preparation-copy"><p v-if="title" class="course-title">{{title}}</p><h2 role="status" aria-live="polite">{{label}}</h2><p :role="error?'alert':undefined">{{description}}</p></div>
  </div>
  <div class="preparation-actions"><slot/></div>
 </section>
</template>
